#include <linux/fs.h>
#include <linux/sysctl.h>

int sysctl_directory_read(struct file *file, struct dir_context *ctx)
{
    struct ctl_table_header *hdr;
    int ret;

    hdr = current_ctl_table_header();
    if (!hdr)
        return -ENOENT;

    ret = iter_dir_dot(file, ctx);
    if (ret)
        goto out;

    ret = iter_dir_dotdot(file, ctx);
    if (ret)
        goto out;

    while (hdr) {
        ret = sysctl_scan(file, ctx, hdr->ctl_table);
        if (ret)
            break;
        hdr = next_ctl_table_header(hdr);
    }

out:
    finish_ctl_table_header(hdr);
    return 0;
}

int sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct seq_file *seq = file->private_data;
    struct sysctl_dir_header *header;
    int ret;

    header = sysctl_get_dir_header(seq);
    if (!header)
        return -ENOENT;

    ret = dir_emit_dots(file, ctx);
    if (ret)
        return ret;

    while (!dir_context_end(ctx)) {
        ret = sysctl_dir_scan(header, file, ctx);
        if (ret)
            break;
    }

    sysctl_finish_dir_header(header);
    return 0;
}

#include <linux/sysctl.h>
#include <linux/fs.h>

int process_sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct sysctl_dir_header *header;
    int ret;

    header = get_sysctl_dir_header(file);
    if (!header)
        return -EFAULT;

    ret = dir_emit_dot(ctx);
    if (ret)
        goto out;

    ret = dir_emit_dotdot(ctx);
    if (ret)
        goto out;

    while (1) {
        struct sysctl_entry *entry;

        entry = get_next_sysctl_entry(header);
        if (!entry)
            break;

        ret = scan_sysctl_entry(entry, ctx);
        if (ret < 0) {
            finish_sysctl_header(header);
            goto out;
        }
    }

out:
    finish_sysctl_header(header);
    return 0;
}

#include <linux/sysctl.h>
#include <linux/fs.h>

int sysctl_dir_read(struct file *file, struct dir_context *ctx) {
    struct ctl_table_header *header;
    int ret;

    header = current_dir_ops->get_header(file);
    if (IS_ERR(header))
        return PTR_ERR(header);

    ret = dir_emit(ctx, ".", 1, (loff_t)1, DT_DIR);
    if (ret)
        return ret;

    ret = dir_emit(ctx, "..", 2, (loff_t)1, DT_DIR);
    if (ret)
        return ret;

    while (header) {
        ret = do_sysctl_scan(header, file, ctx);
        if (ret)
            break;

        header = header->next;
    }

    current_dir_ops->put_header(header);

    return 0;
}

#include <linux/sysctl.h>
#include <linux/fs.h>

int sysctl_file_readdir(struct file *file, struct dir_context *ctx)
{
    struct ctl_table_header *head;
    int ret;

    head = current_ctl_table();
    if (IS_ERR(head))
        return PTR_ERR(head);

    ret = dir_emit_dot(file, ctx);
    if (ret)
        goto out;

    ret = dir_emit_dotdot(file, ctx);
    if (ret)
        goto out;

    while (!ctx->actor) {
        ret = sysctl_scan(file, head, ctx);
        if (ret)
            break;
    }

out:
    put_ctl_table(head);
    return ret ? ret : 0;
}
